/**
 * Normalizes Markdown generated by Docling or fallback parsers.
 * Preserves structural elements (headings, bullet/numbered lists, tables, links, bold/italics),
 * while cleaning up parser artifacts, repeated whitespace, page markers, and empty sections.
 */

// Common Docling / OCR / PDF page artifact patterns
const PAGE_BREAK_RE = /(?:<!--\s*page_break\s*-->|<!--\s*page[_-]?\d+\s*-->|<page_break\s*\/?>|---\s*Page\s+\d+\s*(?:of\s+\d+)?\s*---|\f)/gi;
const DOCLING_IMAGE_PLACEHOLDER_RE = /<!--\s*image(?::[a-zA-Z0-9_-]+)?\s*-->/gi;
const NON_PRINTABLE_RE = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F]/g;
const SOFT_HYPHEN_RE = /\u00AD/g;
const ZERO_WIDTH_RE = /[\u200B-\u200D\uFEFF]/g;

/**
 * Strips repeated consecutive blank lines down to at most one blank line (two newlines).
 */
function cleanBlankLines(text: string): string {
  return text.replace(/\r\n/g, "\n").replace(/\r/g, "\n").replace(/\n{3,}/g, "\n\n");
}

/**
 * Cleans horizontal trailing whitespace while keeping meaningful line indentation for lists.
 */
function cleanLineWhitespace(text: string): string {
  return text
    .split("\n")
    .map((line) => line.replace(/[ \t]+$/, ""))
    .join("\n");
}

/**
 * Removes empty markdown sections where a heading is immediately followed by another heading of same or higher level.
 */
function removeEmptyHeadings(text: string): string {
  const lines = text.split("\n");
  const result: string[] = [];

  for (let i = 0; i < lines.length; i++) {
    const current = lines[i].trim();
    const isHeading = /^#{1,6}\s+/.test(current);

    if (isHeading) {
      // Look ahead to check if next non-empty line is another heading or end of content
      let nextContentLine = "";
      for (let j = i + 1; j < lines.length; j++) {
        if (lines[j].trim()) {
          nextContentLine = lines[j].trim();
          break;
        }
      }

      // If next line is a heading of equal or higher rank (fewer or equal hashes), and this heading has no content, drop this empty heading
      const nextIsHeading = /^#{1,6}\s+/.test(nextContentLine);
      if (nextIsHeading && !nextContentLine.startsWith("#".repeat(current.indexOf(" ") + 1))) {
        // Current heading had no body; skip it
        continue;
      }
    }
    result.push(lines[i]);
  }

  return result.join("\n");
}

/**
 * Normalizes list bullets so standard "-" or "*" or numbers are cleanly indented.
 */
function normalizeListMarkers(text: string): string {
  return text
    .split("\n")
    .map((line) => {
      // Normalize odd bullet symbols like •, ⁃, ◦, ▪ to standard markdown '-'
      return line.replace(/^(\s*)[•⁃◦▪►]\s*/, "$1- ");
    })
    .join("\n");
}

/**
 * Removes obvious identical repeated header/footer lines that appear on multiple pages.
 */
function removeRepeatedHeadersFooters(text: string): string {
  const pages = text.split(PAGE_BREAK_RE);
  if (pages.length <= 1) return text;

  // Track potential repeated lines across multiple pages
  const lineCounts = new Map<string, number>();
  for (const page of pages) {
    const lines = page.split("\n").map((l) => l.trim()).filter((l) => l.length > 5 && l.length < 80);
    const seenOnPage = new Set(lines);
    for (const line of seenOnPage) {
      lineCounts.set(line, (lineCounts.get(line) ?? 0) + 1);
    }
  }

  const repeated = new Set<string>();
  for (const [line, count] of lineCounts.entries()) {
    // If a line appears verbatim on >= 3 pages or on all pages, and is likely a header/footer (e.g. Page 1, "Curriculum Vitae", etc.)
    if (count >= 3 || (count === pages.length && pages.length >= 2)) {
      if (/^(?:page\s+\d+|curriculum\s+vitae|confidential|resume\s+-\s+.*)$/i.test(line)) {
        repeated.add(line);
      }
    }
  }

  if (repeated.size === 0) return text;

  return text
    .split("\n")
    .filter((line) => !repeated.has(line.trim()))
    .join("\n");
}

export function normalizeMarkdown(rawMarkdown: string): string {
  if (!rawMarkdown || typeof rawMarkdown !== "string") return "";

  let md = rawMarkdown;

  // 1. Remove non-printable / zero-width characters and soft hyphens
  md = md.replace(NON_PRINTABLE_RE, "").replace(SOFT_HYPHEN_RE, "").replace(ZERO_WIDTH_RE, "");

  // 2. Remove Docling / PDF page break markers and image placeholders
  md = removeRepeatedHeadersFooters(md);
  md = md.replace(PAGE_BREAK_RE, "\n\n");
  md = md.replace(DOCLING_IMAGE_PLACEHOLDER_RE, "");

  // 3. Normalize bullet characters
  md = normalizeListMarkers(md);

  // 4. Clean line whitespace and multi-blank lines
  md = cleanLineWhitespace(md);
  md = cleanBlankLines(md);

  // 5. Remove empty orphaned headings
  md = removeEmptyHeadings(md);

  // 6. Final trim
  return md.trim();
}
